const COUNTRY_UI={jp:{mark:'JAPAN RAIL',status:'日本全国 · JAPAN',subtitle:'일본 철도 타이핑',title:'일본 철도를<br><span>타이핑하다.</span>',intro:'전국의 실제 역 순서와 선형을 따라 달리는 철도 타이핑 게임.<br>현재역에서 다음역으로, 한국어 역명을 정확히 입력하세요.',network:'JAPAN RAILWAY NETWORK / 日本',categories:[['all','전체'],['jr','JR'],['subway','지하철'],['private','사철'],['third-sector','제3섹터'],['tram','노면전차'],['other','기타'],['shinkansen','신칸센'],['limited-express','특급'],['custom','커스텀']]},kr:{mark:'KOREA TRANSIT',status:'대한민국 · KOREA',subtitle:'대한민국 대중교통 타이핑',title:'대한민국 교통을<br><span>타이핑하다.</span>',intro:'철도·지하철·버스·한강버스의 실제 정차 순서를 따라가는 타이핑 게임.<br>한국어 역·정류장·선착장 이름을 정확히 입력하세요.',network:'KOREA PUBLIC TRANSPORT / 대한민국',categories:[['all','전체'],['subway','지하철·도시철도'],['commuter_rail','광역철도'],['high_speed_rail','고속철도'],['rail','기차'],['bus','버스'],['village_bus','마을버스'],['brt','BRT'],['light_rail','경전철'],['monorail','모노레일'],['river_bus','한강버스'],['other','기타'],['custom','커스텀']]}};
function applyCountryUi(){const ui=COUNTRY_UI[countryId];document.documentElement.dataset.country=countryId;$('#brand-subtitle').textContent=ui.subtitle;$('#home-country-mark').textContent=ui.mark;$('#home-country-subtitle').textContent=ui.subtitle;$('#home-country-status').textContent=ui.status;$('#hero-title').innerHTML=ui.title;$('#home-intro').innerHTML=ui.intro;document.querySelector('.line-select-heading p').textContent=ui.network;$('#category-tabs').innerHTML=ui.categories.map(([id,label],index)=>`<button class="${index?'':'active'}" data-category="${id}">${label}</button>`).join('');$$('[data-country]').forEach(button=>button.classList.toggle('active',button.dataset.country===countryId))}
function refreshCountryCopy(){const korea=countryId==='kr',play=document.querySelector('.launch-menu [data-nav="rail-map"] small'),footer=document.querySelector('.home-footer span:nth-child(2)'),featureButtons=$$('#feature-viewport [data-feature-route]');if(play)play.textContent=korea?'대한민국 교통에서 노선 선택':'일본 전국 철도에서 노선 선택';if(footer)footer.textContent=korea?'대한민국 대중교통 타이핑':'일본 전국 철도 타이핑';if(featureButtons[0])featureButtons[0].dataset.featureRoute=korea?'kr-seoul-line-2':'line-11302';if(featureButtons[1])featureButtons[1].dataset.featureRoute=korea?'kr-shinbundang':'line-28001'}
function configureExplicitDirections(){if(!selected?.directions?.length)return;const select=$('#service-direction'),name=stop=>stop?.ko||stop?.names?.ko||'';select.innerHTML=selected.directions.map(direction=>`<option value="${escapeHtml(direction.id)}">${escapeHtml(direction.names?.ko||direction.id)} · ${escapeHtml(name(direction.stops?.[0]))} → ${escapeHtml(name(direction.stops?.at(-1)))}</option>`).join('')}
